,8:121:D2B8DB134CAACC1CF05D730E49FCA3F78422A2A45E11BCAB3E8A988F62F54748","31,12,2,8:123:2523C5866EABD439EF9215EA95E12A51323EFA9E9300CF26CE95A05683C5F802","31,12,2,8:123:2523C5866EABD439EF9215EA95E12A51323EFA9E9300CF26CE95A05683C5F802","31,12,2,8:123:2523C5866EABD439EF9215EA95E12A51323EFA9E9300CF26CE95A05683C5F802","31,12,2,8:123:2523C5866EABD439EF9215EA95E12A51323EFA9E9300CF26CE95A05683C5F802","31,12,2,8:125:10E5982A1E91941D4D0CB7650C4BB808F6BC17114165C33ACE11FA93019636E5","31,12,2,8:125:10E5982A1E91941D4D0CB7650C4BB808F6BC17114165C33ACE11FA93019636E5","31,12,2,8:125:10E5982A1E91941D4D0CB7650C4BB808F6BC17114165C33ACE11FA93019636E5","31,12,2,8:125:10E5982A1E91941D4D0CB7650C4BB808F6BC17114165C33ACE11FA93019636E5","31,12,2,8:127:DF808DFCF17C7EAC9927DCC4E62CFDC911D57E4B4A53837E6637950910905912","31,12,2,8:127:DF808DFCF17C7EAC9927DCC4E62CFDC911D57E4B4A53837E6637950910905912","31,12,2,8:127:DF808DFCF17C7EAC9927DCC4E62CFDC911D57E4B4A53837E6637950910905912","31,12,2,8:127:DF808DFCF17C7EAC9927DCC4E62CFDC911D57E4B4A53837E6637950910905912","31,12,2,8:128:70A2BD60073CA725D044E1B539E8033B379ABB2431BDADB6CABCDBE7B219BAB2","31,12,2,8:128:70A2BD60073CA725D044E1B539E8033B379ABB2431BDADB6CABCDBE7B219BAB2","31,12,2,8:129:A2B569C67974988B7BFB5348261029A642E3388667DB7BCE4ED29C3983C0C733","31,12,2,8:129:A2B569C67974988B7BFB5348261029A642E3388667DB7BCE4ED29C3983C0C733","31,12,2,8:129:A2B569C67974988B7BFB5348261029A642E3388667DB7BCE4ED29C3983C0C733","31,12,2,8:129:A2B569C67974988B7BFB5348261029A642E3388667DB7BCE4ED29C3983C0C733","24,19,2,1:130:7F46FE71DABEEEB07A3486B50B662FAB3E0ABF255D725F80FF20F7091EE0808A"]}}""";
    private const int MaximumSteps = 10000;
    private static readonly LythonSourceSpan Span = new(0, 0, 1, 1);

    public static IEnumerable<object[]> Cases()
    {
        foreach (var asynchronous in new[] { false, true })
        foreach (var exposed in new[] { false, true })
        foreach (var shape in new[] { "pair", "empty", "wide", "bad-cell", "callback-fail" })
            yield return [asynchronous, exposed, shape];
    }

    [Theory]
    [MemberData(nameof(Cases))]
    public async Task BulkCallsPreserveEveryCheckpointAndOrderedPrefix(bool asynchronous, bool exposed, string shape)
    {
        var source = exposed ? "method=writer.writerows\nreturn method(rows)" : "return writer.writerows(rows)";
        var code = ExecutableScript.Compile(LoweredScript.Lower(LythonFrontend.Compile(source).Script!)).EntryPoint;
        var budget = new LythonMemoryBudget(4 * 1024 * 1024);
        long steps;
        string outcome;
        string[] events;
        using (var owner = budget.CreateScope())
        {
            var (context, trace) = Prepare(owner, shape);
            try
            {
                Assert.Same(PyNone.Instance, await Run(code, context, asynchronous));
                Assert.DoesNotContain(shape, new[] { "bad-cell", "callback-fail" });
                outcome = "None";
            }
            catch (LythonRuntimeException error)
            {
                Assert.Contains(shape, new[] { "bad-cell", "callback-fail" });
                Assert.Equal(shape == "bad-cell" ? "TypeError" : "ValueError", error.ExceptionType);
                outcome = error.ExceptionType + ":" + error.Message;
            }
            steps = context.Limits.ExecutionStepCount;
            events = trace.Events.ToArray();
            var pulls = events.Count(x => x.StartsWith("pull:", StringComparison.Ordinal));
            Assert.Equal(shape == "empty" ? 0 : shape == "wide" ? 65 : 2, pulls);
            Assert.Equal(shape == "empty" ? 0 : shape == "bad-cell" ? 1 : shape == "wide" ? 65 : 2, trace.Writes);
            AssertUnwound(context);
        }
        Assert.Equal(0, budget.ReservedBytes);
        var checkpoints = new List<string>();
        for (var remaining = 0; remaining < steps; remaining++)
        {
            using (var owner = budget.CreateScope())
            {
                var (context, trace) = Prepare(owner, shape);
                context.Limits.ExecutionStepCount = MaximumSteps - remaining;
                var error = await Assert.ThrowsAsync<LythonRuntimeException>(async () => await Run(code, context, asynchronous));
                Assert.Equal(LythonFailureReason.ExecutionStepLimit, error.Attribution?.Reason);
                Assert.Equal(MaximumSteps + 1, context.Limits.ExecutionStepCount);
                var location = error.Span is { } p ? $"{p.Start},{p.Length},{p.Line},{p.Column}" : "-";
                // Retain exact final events and a stable digest for each prefix
                // instead of quadratically repeating all wide-row event text.
                var digest = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(trace.Events))));
                checkpoints.Add($"{location}:{trace.Events.Count}:{digest}");
                AssertUnwound(context);
            }
            Assert.Equal(0, budget.ReservedBytes);
        }
        using var frozen = JsonDocument.Parse(FrozenGuards);
        var guard = frozen.RootElement.GetProperty($"{asynchronous}:{exposed}:{shape}");
        Assert.Equal(guard.GetProperty("steps").GetInt64(), steps);
        Assert.Equal(guard.GetProperty("outcome").GetString(), outcome);
        Assert.Equal(guard.GetProperty("events").EnumerateArray().Select(x => x.GetString()), events);
        Assert.Equal(guard.GetProperty("checkpoints").EnumerateArray().Select(x => x.GetString()), checkpoints);
        output.WriteLine("CSV_WRITEROWS_GUARDS:" + JsonSerializer.Serialize(new { asynchronous, exposed, shape, steps, outcome, events, checkpoints }));
    }

    private static (Context, Trace) Prepare(ILythonMemoryBudget owner, string shape)
    {
        var context = new Context(new MockLythonHost(), new LythonRunOptions { MemoryBudget = owner, MaxExecutionSteps = MaximumSteps });
        var trace = new Trace(context.MemoryGovernor, shape == "callback-fail");
        context.Variables["writer"] = new LythonRuntime.CsvWriterObject(CsvWriterowCallBoundaryTests.Options(), trace, context.MemoryGovernor, Span);
        var text = PyString.FromString("a", context.MemoryGovernor, Span);
        var row = new PyList([text], context.MemoryGovernor, Span);
        var count = shape == "empty" ? 0 : shape == "wide" ? 65 : 3;
        var rows = Enumerable.Repeat<object>(row, count).ToArray();
        if (shape == "pair") Array.Resize(ref rows, 2);
        if (shape == "bad-cell") rows[1] = new PyTuple([new object()], context.MemoryGovernor, Span);
        context.Variables["rows"] = new Rows(rows, trace.Events);
        return (context, trace);
    }

    private static ValueTask<object?> Run(ExecutableCodeObject code, Context context, bool asynchronous)
        => asynchronous ? LythonRuntime.ExecuteExecutableCodeObjectAsync(code, context)
            : ValueTask.FromResult(LythonRuntime.ExecuteExecutableCodeObject(code, context, default, null));

    private static void AssertUnwound(Context context)
    {
        Assert.Null(context.CurrentExecutableFrame);
        Assert.Equal(0, context.Limits.CurrentInterpreterDepth);
        Assert.Equal(0, context.Limits.CurrentRecursionDepth);
        Assert.Equal(0, context.MemoryGovernor.CurrentReservedBytes);
    }

    private sealed class Rows(object[] values, List<string> events) : IEnumerable<object>
    {
        public IEnumerator<object> GetEnumerator()
        {
            for (var i = 0; i < values.Length; i++)
            {
                events.Add("pull:" + i);
                yield return values[i];
            }
        }
        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();
    }

    private sealed class Trace(MemoryGovernor governor, bool fail) : LythonRuntime.ICallable
    {
        internal readonly List<string> Events = [];
        internal int Writes;
        private readonly PyString _ignored = PyString.FromString("ignored", governor, Span);
        public object Invoke(CallArgumentValue[] arguments, LythonSourceSpan span, Context context)
        {
            var text = (PyString)arguments[0].Value;
            Assert.Same(governor, text.OwnerMemoryGovernor);
            Events.Add("write:" + text.AsString());
            Writes++;
            if (fail && Writes == 2) throw new LythonRuntimeException("ValueError", "callback failed", span);
            return _ignored;
        }
    }
}
